		t.Fatalf("refresh did not derive episodes: %+v", source)
	}
	if _, err := os.Stat(filepath.Join(brainDir, filepath.FromSlash(patternCorpusPath))); err != nil {
		t.Fatalf("refresh did not publish corpus: %v", err)
