	if err == nil || !strings.Contains(err.Error(), "no_egress") {
		t.Fatalf("verify no-egress error = %v\n%s", err, out)
	}
	if after := treeContentHash(t, brainDir); after != before {
		t.Fatal("no-egress verification changed derived brain state")
	}
