		t.Fatalf("replay steps = %+v", replay.Steps)
	}
	if replay.Total != 2 || len(replay.Nodes) != 2 || len(replay.Edges) != 2 {
		t.Fatalf("replay subgraph = total %d nodes %d edges %d", replay.Total, len(replay.Nodes), len(replay.Edges))
	}
}

